  const ring = (t, cx, cz, r0, r1, n, s0, s1) => { for (let i = 0; i < n; i++) { const a = i / n * TAU + wrr(-0.3, 0.3), r = wrr(r0, r1), x = cx + Math.cos(a) * r, z = cz + Math.sin(a) * r; if (heightAt(x, z) > 1.2) add(t, x, z, wrr(s0 || 0.9, s1 || 1.2)); } };
