    let ov = null; if (geos[t][1]) { ov = windShadow(new THREE.InstancedMesh(geos[t][1], mat === MAT_GLOW ? MAT_VC : mat, c)); ov.frustumCulled = false; ov.receiveShadow = true; scene.add(ov); }
